1595	function resolveRunSignal(options) {
1596	  if (options === undefined) return null;
1597	  if (!isUsableObject(options)) {
1598	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1599	  }
1600	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1601	  const { signal } = options;
1602	  if (signal instanceof AbortSignal) return signal;
1603	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1604	}
1605	
1606	export function executeWorkflow(workflow, input = {}) {
1607	  const nodes = validateWorkflow(workflow);
1608	  // Business operations are asynchronous: the synchronous entry must refuse
1609	  // a workflow that names any before a single node executes.
1610	  for (const node of nodes.values()) {
1611	    const binding = actionBindings.get(node);
1612	    if (binding && binding.name !== null) {
1613	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1614	    }
1615	  }
1616	
1617	  const state = createRunState(nodes, workflow, input);
1618	
1619	  for (;;) {
1620	    const step = advanceSchedule(state);
1621	
1622	    if (step.kind === 'blocked') {
1623	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1624	    }
1625	    if (step.kind === 'completed') {
1626	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1627	    }
1628	    if (step.kind === 'end') continue;
1629	
1630	    const early = applyRegularNode(step.node, state);
1631	    if (early) return early;
1632	  }
1633	}
1634	
1635	// Attaches compensation results to a failed run. Successful outputs and the
1636	// original terminal status stay untouched; compensation records live on
1637	// their own fields, never in the regular node trace.
1638	async function withCompensation(result, state, operations) {
1639	  const outcome = await compensateRun(state, operations);
1640	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1641	  result.compensationAttempts = outcome.attempts;
1642	  return result;
1643	}
1644	
1645	// The cancelled terminal shape: the run stops where it is, keeps the
1646	// context, trace and attempt records produced so far, and never carries a
1647	// success result. Compensation for already-succeeded actions is attached by
1648	// withCompensation under the usual rules.
1649	function cancelledResult(state) {
1650	  return {
1651	    status: 'cancelled',
1652	    context: state.context,
1653	    trace: state.trace,
1654	    actionAttempts: state.actionAttempts,
1655	  };
1656	}
1657	
1658	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1659	  const signal = resolveRunSignal(options);
1660	  const nodes = validateWorkflow(workflow);
1661	  verifyOperations(nodes, operations);
1662	
1663	  const state = createRunState(nodes, workflow, input);
1664	
1665	  // A signal that is already aborted stops the run before the first node —
1666	  // but only after the definition and the operation registrations above have
1667	  // been checked. Nothing executes and nothing is compensated.
1668	  if (signal && signal.aborted) {
1669	    return withCompensation(cancelledResult(state), state, operations);
1670	  }
1671	
1672	  for (;;) {
1673	    // Once the signal fires, no new regular node runs and no new business
1674	    // action attempt starts; the run ends cancelled with whatever state it
1675	    // reached, even if an end node was already visited on another branch.
1676	    if (signal && signal.aborted) {
1677	      return withCompensation(cancelledResult(state), state, operations);
1678	    }
1679	
1680	    const step = advanceSchedule(state);
1681	
1682	    if (step.kind === 'blocked') {
1683	      // Unmet dependencies end the run; successful compensable actions are
1684	      // rolled back even though an end node may already have been reached.
1685	      return withCompensation({
1686	        status: 'blocked', context: state.context, trace: state.trace,
1687	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1688	      }, state, operations);
1689	    }
1690	    if (step.kind === 'completed') {
1691	      // A completed run never invokes compensation.
1692	      return {
1693	        status: 'completed', result: state.endResult, context: state.context,
1694	        trace: state.trace, actionAttempts: state.actionAttempts,
1695	        compensationStatus: 'not_needed', compensationAttempts: [],
1696	      };
1697	    }
1698	    if (step.kind === 'end') continue;
1699	
1700	    const ready = step.node;
1701	    if (ready.type === 'action') {
1702	      const binding = actionBindings.get(ready);
1703	      if (binding.name !== null) {
1704	        // Nodes execute one at a time in declaration order; awaiting here
1705	        // never lets another node jump ahead.
1706	        const actionResult = await runBusinessAction(
1707	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1708	        if (!actionResult.ok) {
1709	          if (actionResult.cancelled) {
1710	            // Cancelled while the action was in flight or waiting to retry:
1711	            // the attempt records produced so far stay as they are.
1712	            return withCompensation(cancelledResult(state), state, operations);
1713	          }
1714	          // Retries are exhausted: stop immediately with prior input/output
1715	          // preserved, no output for this node and no successors activated —
1716	          // even if an end node was already reached — then compensate every
1717	          // earlier successful action that asked for it.
1718	          return withCompensation({
1719	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1720	            error: actionResult.error, context: state.context, trace: state.trace,
1721	            actionAttempts: state.actionAttempts,
1722	          }, state, operations);
1723	        }
1724	        // Capture the compensation snapshots from the state before the new
1725	        // output key lands: the action's own return value is handed to the
1726	        // compensation separately as its third argument.
1727	        const compensationSnapshot = binding.compensation === null ? null : {
1728	          input: structuredClone(state.context.input),
1729	          output: structuredClone(state.context.output),
1730	          result: structuredClone(actionResult.value),
1731	        };
1732	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1733	        if (compensationSnapshot) {
1734	          // Each node completes at most once, so retried-then-successful
1735	          // actions and shared join nodes are scheduled for compensation
1736	          // exactly once.
1737	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1738	        }
1739	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1740	        state.completed.add(ready.id);
1741	        continue;
1742	      }
1743	    }
1744	
1745	    const early = applyRegularNode(ready, state);
1746	    if (early) {
1747	      early.actionAttempts = state.actionAttempts;
1748	      // A failed form (invalid_input) or failed condition evaluation
1749	      // (invalid_condition) ends normal execution and triggers compensation
1750	      // of the successful business actions that ran earlier.
1751	      return withCompensation(early, state, operations);
1752	    }
1753	  }
