    // even when this was the last attempt the run could have made.
    if (signal && signal.aborted) {
      collect(record);
      return { ok: false, cancelled: true, error: lastReason };
    }

    record.nextDelayMs = attempt < retry.attempts ? retryDelay(retry, attempt) : 0;
    collect(record);
